package warranty

import (
	"errors"
	"math"
	"testing"
	"time"
)

func TestLongWarrantyScratch(t *testing.T) {
	purchase := time.Date(2026, 1, 1, 0, 0, 0, 123456789, time.UTC)

	for _, days := range []int{106751, 106752, 200000} {
		s := NewStore()
		id := "p"
		if err := s.RegisterProductHelper(id, purchaseTimeHelper(purchase), days); err != nil {
			t.Fatalf("register %d days: %v", days, err)
		}
		if err := s.SubmitRequest("r", id, "F1"); err != nil {
			t.Fatal(err)
		}
		e, err := s.Evaluate("r", purchase)
		if err != nil {
			t.Fatal(err)
		}
		if !e.Eligible {
			t.Fatalf("days=%d: not eligible on purchase day: %v", days, e.Reasons)
		}
		want := purchase.Add(time.Duration(days-100000) * 24 * time.Hour).Add(100000 * 24 * time.Hour)
		if !e.WarrantyExpiry.Equal(want) {
			t.Fatalf("days=%d: expiry=%v want %v", days, e.WarrantyExpiry, want)
		}
		if e.WarrantyExpiry.Nanosecond() != 123456789 {
			t.Fatalf("days=%d: sub-second precision lost: %v", days, e.WarrantyExpiry)
		}
		// distinct expiries, not a shared cap
		if days == 106752 {
			if got, wantSec := e.WarrantyExpiry.Unix()-purchase.Unix(), int64(days)*86400; got != wantSec {
				t.Fatalf("days=%d: expiry offset=%ds want %ds", days, got, wantSec)
			}
		}
		// reserve just before expiry works; at expiry rejected
		if err := s.RegisterPart("sp", 10); err != nil {
			t.Fatal(err)
		}
		if _, err := s.Reserve("c1", "r", "sp", 1, e.WarrantyExpiry.Add(time.Hour), e.WarrantyExpiry.Add(-time.Second)); err != nil {
			t.Fatalf("days=%d: reserve before expiry: %v", days, err)
		}
		if _, err := s.Reserve("c2", "r", "sp", 1, e.WarrantyExpiry.Add(2*time.Hour), e.WarrantyExpiry); !errors.Is(err, ErrIneligible) {
			t.Fatalf("days=%d: reserve at expiry = %v, want ErrIneligible", days, err)
		}
		hist, _ := s.RequestHistory("r")
		last := hist[len(hist)-1]
		if last.Eligibility == nil || !last.Eligibility.WarrantyExpiry.Equal(want) || last.Eligibility.WarrantyDays != days || !last.Eligibility.PurchaseTime.Equal(purchase) {
			t.Fatalf("days=%d: history eligibility basis wrong: %+v", days, last.Eligibility)
		}
	}

	// distinct expiry instants across the three terms
	expiries := map[int64]int{}
	for _, days := range []int{106751, 106752, 200000} {
		s := NewStore()
		_ = s.RegisterProduct("p", purchase, days, nil)
		_ = s.SubmitRequest("r", "p", "F1")
		e, _ := s.Evaluate("r", purchase)
		expiries[e.WarrantyExpiry.Unix()] = days
	}
	if len(expiries) != 3 {
		t.Fatalf("expiries not distinct: %v", expiries)
	}

	// unrepresentable term -> ErrInvalidParam, not saved; re-register works
	s := NewStore()
	if err := s.RegisterProduct("p", purchase, math.MaxInt32, nil); !errors.Is(err, ErrInvalidParam) {
		t.Fatalf("huge days = %v, want ErrInvalidParam", err)
	}
	if _, err := s.Product("p"); !errors.Is(err, ErrNotFound) {
		t.Fatalf("product should not be saved: %v", err)
	}
	if err := s.RegisterProduct("p", purchase, 30, nil); err != nil {
		t.Fatalf("re-register with valid term: %v", err)
	}
	// zero/negative still rejected
	if err := s.RegisterProduct("z", purchase, 0, nil); !errors.Is(err, ErrInvalidParam) {
		t.Fatalf("zero days = %v", err)
	}
	if err := s.RegisterProduct("n", purchase, -5, nil); !errors.Is(err, ErrInvalidParam) {
		t.Fatalf("negative days = %v", err)
	}
}

